mapper.update:
UPDATE migration_run
   SET status = #{status}, started_at = #{startedAt}, finished_at = #{finishedAt}, attempt_count = #{attemptCount},
       error_message = #{errorMessage}, error_count = #{errorCount}, info_count = #{infoCount},
       inserted_users = #{insertedUsers}, inserted_projects = #{insertedProjects},
       inserted_applications = #{insertedApplications}, inserted_reviews = #{insertedReviews}
 WHERE id = #{id}

mapper.select:
SELECT 'stg_user' AS table_name, count(*) AS cnt FROM stg_user WHERE migration_run_id = #{runId}
UNION ALL SELECT 'stg_project', count(*) FROM stg_project WHERE migration_run_id = #{runId}
UNION ALL SELECT 'stg_submission', count(*) FROM stg_submission WHERE migration_run_id = #{runId}
UNION ALL SELECT 'stg_review', count(*) FROM stg_review WHERE migration_run_id = #{runId}

