mapper.select:
SELECT id, table_name, row_no, source_key, issue_type, severity, message
  FROM migration_issue
 WHERE migration_run_id = #{runId}
AND table_name = #{tableName}
AND severity = #{severity}
 ORDER BY CASE table_name WHEN 'stg_user' THEN 1 WHEN 'stg_project' THEN 2 WHEN 'stg_submission' THEN 3 ELSE 4 END, row_no, id
